# region: sift
def sift(raw):
    out = []
    for tok in raw:
        s = tok.strip()
        if s.isdigit() and int(s) > 0:
            out.append(int(s))
    return out

# region: digest
def digest(xs, offset=4):
    return [v + offset for v in xs]

# region: gather
def gather(xs, limit=5):
    return [v if v <= limit else limit for v in xs[1:]]

# region: shape
def shape(xs):
    n = len(xs)
    return {'n': n, 'mean': (sum(xs) / n) if n else 0.0, 'max': max(xs) if xs else 0}

# region: intake
def intake(summary, bar=2):
    out = dict(summary)
    out['grade'] = 'high' if summary.get('n', 0) >= bar else 'low'
    return out

# region: run
def run(raw):
    return intake(shape(gather(digest(sift(raw)))))

